const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(data[0]);

const right = new Array(61).fill(0);
const left = new Array(61).fill(0);

for (let i = 0; i < n; i++) {
  const size = Number(data[1 + 2 * i]);
  const side = data[2 + 2 * i];

  if (side === 'D') {
    right[size]++;
  } else {
    left[size]++;
  }
}

let pairs = 0;
for (let size = 30; size <= 60; size++) {
  pairs += Math.min(right[size], left[size]);
}

console.log(pairs);
